import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.CL3B3Tmm.js";const g=JSON.parse('{"title":"Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"security.md","filePath":"security.md","lastUpdated":null}'),s={name:"security.md"};function o(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="Security-Model" tabindex="-1">Security Model <a class="header-anchor" href="#Security-Model" aria-label="Permalink to &quot;Security Model {#Security-Model}&quot;">​</a></h1><p>Kaimon executes arbitrary Julia code on your machine, so controlling access is important. The security system provides three modes, API key authentication, and IP allowlisting to match different trust environments.</p><h2 id="Security-Modes" tabindex="-1">Security Modes <a class="header-anchor" href="#Security-Modes" aria-label="Permalink to &quot;Security Modes {#Security-Modes}&quot;">​</a></h2><p>Kaimon&#39;s MCP endpoint runs in one of three modes. The mode decides what a request must carry and where it may come from:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mode</th><th style="text-align:right;">API key</th><th style="text-align:right;">Client IP</th></tr></thead><tbody><tr><td style="text-align:right;"><code>strict</code></td><td style="text-align:right;">Required</td><td style="text-align:right;">Must be in the IP allowlist</td></tr><tr><td style="text-align:right;"><code>relaxed</code></td><td style="text-align:right;">Required</td><td style="text-align:right;">Any</td></tr><tr><td style="text-align:right;"><code>lax</code></td><td style="text-align:right;">Not checked</td><td style="text-align:right;">Localhost only</td></tr></tbody></table><h3 id="strict" tabindex="-1">Strict <a class="header-anchor" href="#strict" aria-label="Permalink to &quot;Strict&quot;">​</a></h3><p>Every request needs a valid API key and must come from an allowlisted IP. The default allowlist is <code>127.0.0.1</code> and <code>::1</code>, so a local-only setup works without changes. Use it on shared machines, or whenever you want explicit access control.</p><h3 id="relaxed" tabindex="-1">Relaxed <a class="header-anchor" href="#relaxed" aria-label="Permalink to &quot;Relaxed&quot;">​</a></h3><p>Every request needs a valid API key, from any IP. Use it when clients on other machines connect directly.</p><h3 id="lax" tabindex="-1">Lax <a class="header-anchor" href="#lax" aria-label="Permalink to &quot;Lax&quot;">​</a></h3><p>No credential is checked, and only requests from localhost are accepted. Any process on the machine can call every tool, including <code>ex</code>, which runs arbitrary Julia code as you. Use it on a single-user machine where you trust everything that runs.</p><p>Change the mode with <code>Kaimon.set_security_mode(:strict)</code> (or <code>:relaxed</code>, <code>:lax</code>), then restart Kaimon.</p><h2 id="API-Key-Management" tabindex="-1">API Key Management <a class="header-anchor" href="#API-Key-Management" aria-label="Permalink to &quot;API Key Management {#API-Key-Management}&quot;">​</a></h2><p>Kaimon provides functions to manage API keys:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Function</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Kaimon.generate_key()</code></td><td style="text-align:right;">Generate a new API key and add it to the configuration. It is printed once.</td></tr><tr><td style="text-align:right;"><code>Kaimon.revoke_key(key)</code></td><td style="text-align:right;">Revoke an existing API key so it can no longer be used.</td></tr><tr><td style="text-align:right;"><code>Kaimon.set_security_mode(mode)</code></td><td style="text-align:right;">Set the mode: <code>:strict</code>, <code>:relaxed</code> or <code>:lax</code>.</td></tr><tr><td style="text-align:right;"><code>Kaimon.security_status()</code></td><td style="text-align:right;">Display the current security mode, active keys, and IP allowlist.</td></tr></tbody></table><h3 id="Using-API-Keys-with-MCP-Clients" tabindex="-1">Using API Keys with MCP Clients <a class="header-anchor" href="#Using-API-Keys-with-MCP-Clients" aria-label="Permalink to &quot;Using API Keys with MCP Clients {#Using-API-Keys-with-MCP-Clients}&quot;">​</a></h3><p>MCP clients send the key in the <code>Authorization</code> header:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer your-api-key-here&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The client installers in the TUI&#39;s Config tab write this header for you when a key is configured. After generating a key or changing the mode, re-run the installer for each client you use.</p><h2 id="Agents-Kaimon-Starts" tabindex="-1">Agents Kaimon Starts <a class="header-anchor" href="#Agents-Kaimon-Starts" aria-label="Permalink to &quot;Agents Kaimon Starts {#Agents-Kaimon-Starts}&quot;">​</a></h2><p>An agent Kaimon spawns (with <code>agent_open</code>, or from a Slate notebook) never receives the API key. It gets its own token instead, minted when it starts and revoked when it ends. The token is the agent&#39;s credential in every mode, and the only way Kaimon identifies the agent: its permission preset, allowlist and the guard against agents spawning agents apply to the calls that carry it. A token left behind in a config file stops working once its agent is gone.</p><p>The token makes an agent&#39;s calls attributable; it does not contain the agent. An agent with unrestricted native file or shell access runs as you, so it can read your own MCP client configs, API key included, and call Kaimon without its token. In <code>lax</code> mode it needs no credential at all. To hold an agent to its preset, deny it native file and shell tools (the <code>notebook</code> preset does this for Claude and opencode agents) or run it in an OS-level sandbox, which Kaimon can set up on Linux (below).</p><h2 id="Confining-Agents-Linux" tabindex="-1">Confining Agents (Linux) <a class="header-anchor" href="#Confining-Agents-Linux" aria-label="Permalink to &quot;Confining Agents (Linux) {#Confining-Agents-Linux}&quot;">​</a></h2><p>On Linux, Kaimon can confine the processes of the agents it starts with the kernel&#39;s Landlock (Linux 5.13 or later). Set <code>KAIMON_CONFINE_POLICY</code> to a policy file before starting Kaimon:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># what agents may not read</span></span>
<span class="line"><span>deny /home/me/.ssh</span></span>
<span class="line"><span>deny /home/me/.config</span></span>
<span class="line"><span>deny /srv/app/secrets</span></span></code></pre></div><p>A confined agent, and everything it runs, can read all but the <code>deny</code> paths and write only its working directory, its own temporary directory and its CLI&#39;s state folder (<code>~/.claude</code>, <code>~/.codex</code>, and so on). The kernel enforces this, so it holds for the agent&#39;s own file and shell tools, which a check of tool-call arguments cannot. A policy file may also hold <code>allow</code> lines (paths inside denied folders that stay readable), <code>write</code> lines (more folders every agent may write) and <code>unset</code> lines (environment variables removed before the agent starts).</p><p><code>agent_open</code> takes <code>confine_write</code>, more folders this agent may write, and <code>confine_allow</code>, paths outside its working directory it is to read even where the policy denies them. A Claude agent also gets the folders in <code>confine_allow</code> as working folders.</p><p>Confinement covers the agent&#39;s process only. Kaimon tools the agent calls, such as <code>ex</code>, run in the session they target, which is not confined, so its permission preset still decides what those tools may do. Agents that run inside Kaimon (Ollama, vmlx) have no process of their own and are not confined. On other platforms the policy is not applied.</p><h2 id="Seeing-the-Security-State" tabindex="-1">Seeing the Security State <a class="header-anchor" href="#Seeing-the-Security-State" aria-label="Permalink to &quot;Seeing the Security State {#Seeing-the-Security-State}&quot;">​</a></h2><p>The TUI&#39;s Server tab shows the active mode and how many requests the server has refused, with the reason for the most recent one: a missing or invalid API key, an IP outside the allowlist, a revoked agent token, or a session that belongs to another agent. In the Agents tab, each agent shows a short fingerprint of its token (never the token itself), the MCP session bound to it, and when it last made a call.</p><h2 id="IP-Allowlists" tabindex="-1">IP Allowlists <a class="header-anchor" href="#IP-Allowlists" aria-label="Permalink to &quot;IP Allowlists {#IP-Allowlists}&quot;">​</a></h2><p>The allowlist applies in <code>strict</code> mode:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Function</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;"><code>allow_ip(ip)</code></td><td style="text-align:right;">Add an IP address to the allowlist.</td></tr><tr><td style="text-align:right;"><code>deny_ip(ip)</code></td><td style="text-align:right;">Remove an IP address from the allowlist.</td></tr></tbody></table><p>Only allowlisted IPs are accepted, so an empty allowlist refuses every request. <code>relaxed</code> mode does not check the client IP, and <code>lax</code> mode accepts localhost only.</p><h2 id="Gate-TCP-Authentication" tabindex="-1">Gate (TCP) Authentication <a class="header-anchor" href="#Gate-TCP-Authentication" aria-label="Permalink to &quot;Gate (TCP) Authentication {#Gate-TCP-Authentication}&quot;">​</a></h2><p>The sections above govern the <strong>MCP HTTP server</strong>. A separate concern is the <strong>gate</strong> (<code>KaimonGate</code>) when it binds a TCP socket for remote access — see <a href="/Kaimon.jl/dev/gate#tcp-mode">TCP Mode</a>. The gate enforces its own token, independent of the MCP server&#39;s API keys:</p><ul><li><p><strong>Standalone <code>KaimonGate</code></strong> (the lightweight <code>]add KaimonGate</code> install, e.g. on a remote/compute node): the gate token comes <strong>only</strong> from the <code>KAIMON_GATE_TOKEN</code> environment variable. If it is unset, the TCP gate is <strong>open</strong> — any client that can reach the port can evaluate code in the session. Always set <code>KAIMON_GATE_TOKEN</code> before exposing a gate on a shared or network-reachable host (and prefer binding to <code>127.0.0.1</code> + an SSH tunnel over <code>0.0.0.0</code>).</p></li><li><p><strong>Full <code>Kaimon</code></strong> install: the token is taken from <code>KAIMON_GATE_TOKEN</code> if set, otherwise derived from your security config&#39;s API keys when the config mode is not <code>:lax</code>. So a strict/relaxed config automatically protects TCP gates started by that process.</p></li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>IPC (Unix-socket) gates are protected by filesystem permissions on <code>~/.cache/kaimon/sock/</code> and do not use a token. The token only applies to TCP mode. A <code>0.0.0.0</code> bind with no token exposes a remote code-execution endpoint to the network.</p></div><h2 id="Encrypted-Transport-CURVE" tabindex="-1">Encrypted Transport (CURVE) <a class="header-anchor" href="#Encrypted-Transport-CURVE" aria-label="Permalink to &quot;Encrypted Transport (CURVE) {#Encrypted-Transport-CURVE}&quot;">​</a></h2><p>A bearer token proves <em>who may call</em> a TCP gate, but it travels in the clear and the traffic is unencrypted. For a gate exposed beyond <code>localhost</code>, enable <strong>CURVE</strong> — ZMQ&#39;s Curve25519 transport — for confidentiality, integrity, and <strong>mutual</strong> authentication on the wire. CURVE replaces the SSH tunnel as the security layer (server pinning + a client allow-list), and its <strong>soy-free mode</strong> SSH-bootstraps the server pin to close the TOFU first-use gap entirely.</p><p>See <strong><a href="./curve">Encrypted Transport (CURVE)</a></strong> for the full trust model, key management (<code>[k]</code> in the TUI), soy-free verification, and stall diagnostics.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Security settings are stored in a global JSON configuration file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/kaimon/config.json</span></span></code></pre></div><p>Legacy <code>security.json</code> files are automatically migrated to <code>config.json</code> on first access.</p><h3 id="Configuration-Format" tabindex="-1">Configuration Format <a class="header-anchor" href="#Configuration-Format" aria-label="Permalink to &quot;Configuration Format {#Configuration-Format}&quot;">​</a></h3><p>A typical <code>config.json</code> file:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;api_keys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;key-abc123...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowed_ips&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;::1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="Setup-Wizard" tabindex="-1">Setup Wizard <a class="header-anchor" href="#Setup-Wizard" aria-label="Permalink to &quot;Setup Wizard {#Setup-Wizard}&quot;">​</a></h2><p>For interactive configuration, use the setup wizard:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Kaimon</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Kaimon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">setup_wizard_tui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>The wizard walks you through:</p><ol><li><p>Choosing a security mode (Strict, Relaxed, or Lax).</p></li><li><p>Generating an initial API key.</p></li><li><p>Configuring IP allowlists.</p></li><li><p>Writing the configuration file to the appropriate location.</p></li></ol><p>This is the recommended way to configure security for the first time.</p>`,54)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
